"""
Alert model for threat notifications.
"""
import uuid
from datetime import datetime, timezone

from sqlalchemy import String, Boolean, Text, DateTime, ForeignKey
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, UUIDMixin, TimestampMixin, UUID, JSONB


class Alert(Base, UUIDMixin, TimestampMixin):
    """A threat alert generated by the system."""
    __tablename__ = "alerts"

    domain_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID, ForeignKey("domains.id", ondelete="CASCADE"), nullable=True, index=True
    )
    alert_type: Mapped[str] = mapped_column(String(50), nullable=False, default="threat_detection")
    severity: Mapped[str] = mapped_column(String(10), nullable=False, default="MEDIUM")
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    description: Mapped[str | None] = mapped_column(Text, nullable=True)
    is_read: Mapped[bool] = mapped_column(Boolean, default=False, nullable=False)
    is_resolved: Mapped[bool] = mapped_column(Boolean, default=False, nullable=False)
    metadata_: Mapped[dict | None] = mapped_column("metadata", JSONB, nullable=True)
    resolved_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)

    # Relationships
    domain = relationship("Domain", back_populates="alerts")

    def __repr__(self):
        return f"<Alert(title={self.title}, severity={self.severity})>"
